type CartState = { items: string[] };
export const initialState: CartState = { items: [] };

export function cartReducer(state: CartState, action: { type: 'cart/add'; id: string }): CartState {
  if (action.type === 'cart/add') {
    state.items.push(action.id);
    return { ...state };
  }
  return state;
}

// cartReducer.test.ts
it('adds the first item', () => {
  expect(cartReducer(initialState, { type: 'cart/add', id: 'a' }).items).toEqual(['a']);
});

it('adds an item to an empty cart', () => {
  expect(cartReducer(initialState, { type: 'cart/add', id: 'b' }).items).toEqual(['b']);
});

async function retry<T>(fn: () => Promise<T>, delayMs: number): Promise<T> {
  try {
    return await fn();
  } catch {
    await new Promise((resolve) => setTimeout(resolve, delayMs));
    return fn();
  }
}

it('retries once after one second', async () => {
  jest.useFakeTimers();
  const fetchPrices = jest.fn()
    .mockRejectedValueOnce(new Error('503'))
    .mockResolvedValueOnce('ok');

  const result = retry(fetchPrices, 1000);
  jest.advanceTimersByTime(1000);

  await expect(result).resolves.toBe('ok');
});
